/**
 * Circular Motion simulation.
 *
 * omega = 2*pi / period
 * theta(t) = omega*t
 * x(t) = r*cos(theta), y(t) = r*sin(theta)
 * speed = omega*r (constant)
 * centripetal acceleration = omega^2*r = speed^2/r, toward the center
 *
 * Always computed here, in code -- never fetched from a server and never
 * generated by AI. Mirrors apps/physics/simulations_circular_motion.py
 * exactly (same bounds, same formulas), the same way projectile.js mirrors
 * simulations_projectile.py. This file owns its own physics, SVG and
 * controls; it shares only the run-loop/registry shell in lab.js.
 */
(function (window, document) {
  "use strict";

  var MIN_RADIUS_M = 0.5;
  var MAX_RADIUS_M = 10.0;
  var MIN_PERIOD_S = 0.5;
  var MAX_PERIOD_S = 20.0;
  var MAX_TIME_S = 60.0;

  function clampRadius(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_RADIUS_M, Math.min(MAX_RADIUS_M, n));
  }
  function clampPeriod(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_PERIOD_S, Math.min(MAX_PERIOD_S, n));
  }

  function computeState(radius, period, t) {
    radius = clampRadius(radius);
    period = clampPeriod(period);
    t = Math.max(0, Math.min(MAX_TIME_S, Number(t)));
    var omega = (2 * Math.PI) / period;
    var theta = omega * t;
    var x = radius * Math.cos(theta);
    var y = radius * Math.sin(theta);
    var speed = omega * radius;
    var vx = -omega * radius * Math.sin(theta);
    var vy = omega * radius * Math.cos(theta);
    var centripetalAccel = omega * omega * radius;
    var angleDeg = ((theta * 180) / Math.PI) % 360;
    if (angleDeg < 0) angleDeg += 360;
    return {
      x: x,
      y: y,
      vx: vx,
      vy: vy,
      speed: speed,
      centripetalAccel: centripetalAccel,
      angleDeg: angleDeg
    };
  }

  // Geometry constants for the SVG scene/graph.
  var CENTER_X_PX = 200;
  var CENTER_Y_PX = 140;
  var USABLE_RADIUS_PX = 108;
  var STEP_S = 0.1;
  var REDUCED_MOTION_STOP_S = 6;

  function readNum(el, name, fallback) {
    var raw = el.getAttribute("data-" + name);
    var value = parseFloat(raw);
    return isFinite(value) ? value : fallback;
  }
  function round4(n) {
    return Math.round(n * 10000) / 10000;
  }

  function createCircularMotionSim(root, config, lab) {
    var state = {
      radius: clampRadius(readNum(root, "radius", 2)),
      period: clampPeriod(readNum(root, "period", 4)),
      timeS: 0,
      x: 0,
      y: 0,
      speed: 0,
      centripetalAccel: 0,
      angleDeg: 0,
      scale: 10
    };

    var trace = []; // [t, y] samples, feeds the y-vs-time graph
    var maxAbsY = 1;

    var el = {
      scene: root.querySelector("[data-lab-scene]"),
      sceneDesc: root.querySelector("[data-scene-desc]"),
      marker: root.querySelector("[data-cart]"),
      orbit: root.querySelector("[data-orbit-circle]"),
      radiusLine: root.querySelector("[data-radius-line]"),
      sceneStatus: root.querySelector("[data-scene-status]"),
      graph: root.querySelector("[data-lab-graph]"),
      graphDesc: root.querySelector("[data-graph-desc]"),
      trace: root.querySelector("[data-lab-trace]"),
      valueRadius: root.querySelector("[data-value-radius]"),
      valuePeriod: root.querySelector("[data-value-period]"),
      valueTime: root.querySelector("[data-value-time]"),
      valueX: root.querySelector("[data-value-x]"),
      valueY: root.querySelector("[data-value-y]"),
      valueSpeed: root.querySelector("[data-value-speed]"),
      valueAccel: root.querySelector("[data-value-accel]"),
      eqSpeed: root.querySelector("[data-eq-speed]"),
      eqAccel: root.querySelector("[data-eq-accel]"),
      outRadius: root.querySelector("[data-out-radius]"),
      outPeriod: root.querySelector("[data-out-period]"),
      inputRadius: root.querySelector("[data-input-radius]"),
      inputPeriod: root.querySelector("[data-input-period]"),
      btnStart: root.querySelector("[data-action-start]"),
      btnPause: root.querySelector("[data-action-pause]"),
      btnReset: root.querySelector("[data-action-reset]"),
      btnStep: root.querySelector("[data-action-step]"),
      inputTime: root.querySelector("[data-input-time]"),
      outTime: root.querySelector("[data-out-time]"),
      motionNote: root.querySelector("[data-motion-note]")
    };

    var loop = lab.createRunLoop(tick, {});

    function updateScale() {
      state.scale = USABLE_RADIUS_PX / state.radius;
    }
    function screenX(xM) {
      return CENTER_X_PX + xM * state.scale;
    }
    function screenY(yM) {
      return CENTER_Y_PX - yM * state.scale;
    }

    function recordTrace() {
      trace.push([round4(state.timeS), round4(state.y)]);
      maxAbsY = Math.max(maxAbsY, Math.abs(state.y));
      // Bound memory for a long-running loop -- keep the most recent window.
      if (trace.length > 2000) trace.shift();
    }

    function setRadius(value) {
      state.radius = clampRadius(value);
      if (el.inputRadius) el.inputRadius.value = String(state.radius);
      if (el.outRadius) el.outRadius.textContent = String(state.radius);
      updateScale();
      setTime(0);
    }
    function setPeriod(value) {
      state.period = clampPeriod(value);
      if (el.inputPeriod) el.inputPeriod.value = String(state.period);
      if (el.outPeriod) el.outPeriod.textContent = String(state.period);
      setTime(0);
    }

    function start() {
      loop.start();
    }
    function pause() {
      loop.stop();
    }
    function reset() {
      loop.stop();
      setTime(0);
    }

    function rebuildTrace(upToT) {
      trace = [];
      maxAbsY = Math.max(1, state.radius);
      var sampleDt = Math.max(upToT / 60, 0.02);
      for (var t = 0; t < upToT - 1e-9; t += sampleDt) {
        var c = computeState(state.radius, state.period, t);
        trace.push([round4(t), round4(c.y)]);
      }
      trace.push([round4(upToT), round4(state.y)]);
    }

    function setTime(value) {
      loop.stop();
      var t = Number(value);
      if (!isFinite(t)) return;
      t = Math.max(0, Math.min(MAX_TIME_S, t));
      var computed = computeState(state.radius, state.period, t);
      state.timeS = t;
      state.x = computed.x;
      state.y = computed.y;
      state.speed = computed.speed;
      state.centripetalAccel = computed.centripetalAccel;
      state.angleDeg = computed.angleDeg;
      rebuildTrace(t);
      if (el.sceneStatus) el.sceneStatus.textContent = "";
      render();
    }

    function stepForward() {
      setTime(state.timeS + STEP_S);
    }

    function tick(dt) {
      if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        if (el.sceneStatus) {
          el.sceneStatus.textContent = "Reached the end of the simulated time window (60 s).";
        }
        return;
      }
      var nextT = Math.min(MAX_TIME_S, state.timeS + dt);
      var computed = computeState(state.radius, state.period, nextT);
      state.timeS = nextT;
      state.x = computed.x;
      state.y = computed.y;
      state.speed = computed.speed;
      state.centripetalAccel = computed.centripetalAccel;
      state.angleDeg = computed.angleDeg;
      recordTrace();

      if (loop.reduced && state.timeS >= REDUCED_MOTION_STOP_S) {
        loop.stop();
      }
      render();
    }

    function renderScene() {
      if (el.marker) {
        el.marker.setAttribute(
          "transform",
          "translate(" + screenX(state.x).toFixed(1) + "," + screenY(state.y).toFixed(1) + ")"
        );
      }
      if (el.orbit) {
        el.orbit.setAttribute("cx", String(CENTER_X_PX));
        el.orbit.setAttribute("cy", String(CENTER_Y_PX));
        el.orbit.setAttribute("r", String(state.radius * state.scale));
      }
      if (el.radiusLine) {
        el.radiusLine.setAttribute("x1", String(CENTER_X_PX));
        el.radiusLine.setAttribute("y1", String(CENTER_Y_PX));
        el.radiusLine.setAttribute("x2", screenX(state.x).toFixed(1));
        el.radiusLine.setAttribute("y2", screenY(state.y).toFixed(1));
      }
      var text =
        "An object moving in a circle of radius " + state.radius.toFixed(1) +
        " metres, completing one revolution every " + state.period.toFixed(1) +
        " seconds. At " + state.timeS.toFixed(1) + " seconds it is at " +
        state.angleDeg.toFixed(0) + " degrees around the circle, moving at " +
        state.speed.toFixed(2) + " metres per second.";
      if (el.scene) el.scene.setAttribute("aria-label", text);
      if (el.sceneDesc) el.sceneDesc.textContent = text;
    }

    function renderGraph() {
      if (!el.trace) return;
      var w = 348, h = 156, left = 40, top = 10, bottom = 6;
      var tMin = trace.length ? trace[0][0] : 0;
      var tMax = Math.max(tMin + 1, state.timeS);
      var yMax = Math.max(1, maxAbsY);
      var points = [];
      for (var i = 0; i < trace.length; i++) {
        var px = left + ((trace[i][0] - tMin) / (tMax - tMin)) * (w - left - 12);
        var py = h - bottom - ((trace[i][1] + yMax) / (2 * yMax)) * (h - top - bottom);
        points.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      el.trace.setAttribute("points", points.join(" "));
      var graphText =
        "y-position vs time. At " + state.timeS.toFixed(1) + " seconds the y-position is " +
        state.y.toFixed(2) + " metres.";
      if (el.graph) el.graph.setAttribute("aria-label", graphText);
      if (el.graphDesc) el.graphDesc.textContent = graphText;
    }

    function render() {
      if (el.valueRadius) el.valueRadius.textContent = String(state.radius);
      if (el.valuePeriod) el.valuePeriod.textContent = String(state.period);
      if (el.valueTime) el.valueTime.textContent = state.timeS.toFixed(2);
      if (el.valueX) el.valueX.textContent = state.x.toFixed(2);
      if (el.valueY) el.valueY.textContent = state.y.toFixed(2);
      if (el.valueSpeed) el.valueSpeed.textContent = state.speed.toFixed(2);
      if (el.valueAccel) el.valueAccel.textContent = state.centripetalAccel.toFixed(2);
      if (el.eqSpeed) el.eqSpeed.textContent = state.speed.toFixed(2);
      if (el.eqAccel) el.eqAccel.textContent = state.centripetalAccel.toFixed(2);
      if (el.inputTime && document.activeElement !== el.inputTime) {
        el.inputTime.value = String(round4(state.timeS));
      }
      if (el.outTime) el.outTime.textContent = state.timeS.toFixed(1);
      renderScene();
      renderGraph();
      root.dispatchEvent(new CustomEvent("lab:state", { detail: getState() }));
    }

    function getState() {
      return {
        radiusM: state.radius,
        periodS: state.period,
        timeS: state.timeS,
        positionXM: state.x,
        positionYM: state.y,
        speedMs: state.speed,
        centripetalAccelerationMs2: state.centripetalAccel,
        running: loop.isRunning()
      };
    }

    if (el.inputRadius) {
      el.inputRadius.addEventListener("input", function () { setRadius(el.inputRadius.value); });
      el.inputRadius.addEventListener("change", function () { setRadius(el.inputRadius.value); });
    }
    if (el.inputPeriod) {
      el.inputPeriod.addEventListener("input", function () { setPeriod(el.inputPeriod.value); });
      el.inputPeriod.addEventListener("change", function () { setPeriod(el.inputPeriod.value); });
    }
    if (el.btnStart) el.btnStart.addEventListener("click", start);
    if (el.btnPause) el.btnPause.addEventListener("click", pause);
    if (el.btnReset) el.btnReset.addEventListener("click", reset);
    if (el.btnStep) el.btnStep.addEventListener("click", stepForward);
    if (el.inputTime) {
      el.inputTime.addEventListener("input", function () { setTime(el.inputTime.value); });
      el.inputTime.addEventListener("change", function () { setTime(el.inputTime.value); });
    }

    if (loop.reduced && el.motionNote) el.motionNote.hidden = false;

    updateScale();
    reset();

    var api = {
      setRadius: setRadius,
      setPeriod: setPeriod,
      start: start,
      pause: pause,
      reset: reset,
      setTime: setTime,
      step: stepForward,
      getState: getState
    };
    root.labInstance = api;
    return api;
  }

  PhysicsLab.register("circular_motion", createCircularMotionSim);

  PhysicsLab.CircularMotion = {
    MIN_RADIUS_M: MIN_RADIUS_M,
    MAX_RADIUS_M: MAX_RADIUS_M,
    MIN_PERIOD_S: MIN_PERIOD_S,
    MAX_PERIOD_S: MAX_PERIOD_S,
    MAX_TIME_S: MAX_TIME_S,
    clampRadius: clampRadius,
    clampPeriod: clampPeriod,
    computeState: computeState
  };
})(window, document);
